package com.oorja.backend.entity;

import com.oorja.backend.entity.enums.SubjectType;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;

/**
 * Metadata for a file attached to a booking — site photos and documents from
 * the customer, and service reports / completion documents generated by ops.
 *
 * The row holds metadata only; the bytes live in object storage (or on local
 * disk in development) under {@link #storageKey}.
 *
 * Deletion is soft: {@link #deletedAt} / {@link #deletedBy} are set and the row
 * is retained as the audit record. A background job removes the underlying
 * object once the retention window has passed, so an accidental delete of an
 * important document is recoverable until then.
 */
@Entity
@Table(name = "booking_attachments")
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class BookingAttachment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "booking_id", nullable = false)
    private Booking booking;

    /** Original filename as uploaded. Metadata only — never part of the storage key. */
    @Column(name = "file_name", nullable = false)
    private String fileName;

    @Column(name = "content_type")
    private String contentType;

    @Column(name = "size_bytes")
    private Long sizeBytes;

    /**
     * Key in the backing store, e.g. {@code bookings/2026/09/TKN-26-00231/8af3….jpg}.
     * Resolved by the configured {@code StorageProvider} — local disk in dev,
     * S3/R2 in production.
     */
    @Column(name = "storage_key", nullable = false, length = 500)
    private String storageKey;

    // ---------- provenance ----------

    /** Who uploaded this — drives the deletion rules. */
    @Enumerated(EnumType.STRING)
    @Column(name = "uploaded_by_type", nullable = false, length = 16)
    @Builder.Default
    private SubjectType uploadedByType = SubjectType.CUSTOMER;

    /** Id of the uploading customer or admin. */
    @Column(name = "uploaded_by")
    private Long uploadedBy;

    /**
     * Admin-generated service reports and completion documents are records of
     * work performed, so a customer can never delete them even though they're
     * attached to that customer's booking.
     */
    @Column(name = "official_document", nullable = false)
    @Builder.Default
    private boolean officialDocument = false;

    @Column(name = "created_at", nullable = false, updatable = false)
    @Builder.Default
    private LocalDateTime createdAt = LocalDateTime.now();

    // ---------- soft delete / audit ----------

    @Column(name = "deleted_at")
    private LocalDateTime deletedAt;

    @Column(name = "deleted_by")
    private Long deletedBy;

    @Enumerated(EnumType.STRING)
    @Column(name = "deleted_by_type", length = 16)
    private SubjectType deletedByType;

    @Column(name = "delete_reason", length = 500)
    private String deleteReason;

    /** Set once the background job has removed the object from storage. */
    @Column(name = "purged_at")
    private LocalDateTime purgedAt;

    public boolean isDeleted() {
        return deletedAt != null;
    }
}
